#!/usr/bin/env bash
# init-dev-environment installer, generated by the claude-code-knowledge
# repository-audit skill. Usage: bash install.sh [--dry-run] <tool-id>...
# Prints one line per tool: present: | missing: (dry-run) | installed: |
# FAILED: <id>, plus a note: line naming tools the caller's PATH cannot find
# (present or installed). Exit 0 = all ok, 1 = a tool failed.
# User level only (never sudo). Binaries land in, or are symlinked into,
# ~/.local/bin. A tool that is already usable is never reinstalled.
set -u
DRY=0
for opt in "$@"; do if [ "$opt" = "--dry-run" ]; then DRY=1; fi; done # any position
BIN="$HOME/.local/bin"
CARGO_BIN="${CARGO_HOME:-$HOME/.cargo}/bin"
ORIG_PATH="${PATH:-}"
export PATH="${PATH:+$PATH:}$BIN:$CARGO_BIN:$HOME/.bun/bin" # append: inherited PATH wins
FAILED=0
OFFPATH="" # tools reachable only through the PATH dirs appended above
TMPD=""    # temp dir of the running recipe; removed on exit and when killed
trap '[ -z "$TMPD" ] || rm -rf "$TMPD"' EXIT
trap 'exit 130' INT TERM HUP

os() { uname -s | tr '[:upper:]' '[:lower:]'; } # linux | darwin
arch() {
  case "$(uname -m)" in
    x86_64 | amd64) echo x64 ;;
    aarch64 | arm64) echo arm64 ;;
    *)
      echo "unsupported architecture: $(uname -m)" >&2
      return 1
      ;;
  esac
}
sha256() { if command -v sha256sum > /dev/null 2>&1; then sha256sum "$@"; else shasum -a 256 "$@"; fi; }

# <path>: 0 when nothing is there; a dangling symlink is removed first
vacant() {
  if [ -L "$1" ] && [ ! -e "$1" ]; then rm -f "$1" || return 1; fi
  [ ! -e "$1" ]
}
link() {
  vacant "$BIN/${1##*/}" || return 0
  ln -s "$1" "$BIN/${1##*/}"
} # never clobber

# <id>: 0 when the tool is usable. The single probe for the dry-run plan and
# the post-install check, so both always agree.
present() {
  case "$1" in
    # rustup ships ~/.cargo/bin proxies for cargo, rustc and rust-analyzer that
    # exist without a toolchain / the component and exit non-zero, so command -v
    # is not enough
    cargo | rustc | rust-analyzer) "$1" --version > /dev/null 2>&1 ;;
    *) command -v "$1" > /dev/null 2>&1 ;;
  esac
}

# <id>: remember a usable tool that the caller's own PATH cannot find
offpath() {
  PATH="$ORIG_PATH" present "$1" && return 0
  case " $OFFPATH " in *" $1 "*) ;; *) OFFPATH="$OFFPATH $1" ;; esac
}

ensure() { # <id>: present | missing (dry-run) | installed | FAILED
  local id="$1" fn="install_${1//-/_}"
  if ! declare -F "$fn" > /dev/null; then
    echo "FAILED: $id (unknown tool id)"
    return 1
  fi
  if present "$id"; then
    echo "present: $id"
    offpath "$id"
    return 0
  fi
  if [ "$DRY" = 1 ]; then
    echo "missing: $id"
    return 0
  fi
  if mkdir -p "$BIN" && "$fn" && present "$id"; then
    echo "installed: $id"
    offpath "$id"
    return 0
  fi
  echo "FAILED: $id"
  return 1
}

# install_<id> recipes. Each chains its steps with && (no set -e: bash ignores
# it inside a function run from an if/&& list), guards every version lookup
# against an empty answer, and removes its temp dir on success and failure
# (a recipe that makes one also records it in TMPD, so the EXIT trap removes it
# when the installer is killed mid-download).
# A recipe that needs a runtime starts with `ensure <dep> &&`.
# ponytail: the download recipes (node, go, bun, cargo, uv, lua-language-server)
# hard-code upstream URLs and are covered only by bash -n, the id/function
# parity check and the no-sudo grep; upgrade path: a base-URL override plus a
# local node:http fixture server, as in rtk-install.bats.

# A numeric .nvmrc / .node-version pin ("18", "v18.19", "20.11.1") at the project
# root, three levels above this script (<root>/.claude/skills/<skill>/); anything
# else (lts/*, node, no file) means no pin.
node_pin() {
  local root p f
  root=$(cd "$(dirname -- "$0")/../../.." 2> /dev/null && pwd) || return 0
  for f in .nvmrc .node-version; do
    p=""
    [ -r "$root/$f" ] && { read -r p < "$root/$f" || :; }
    p=${p//[[:space:]]/}
    p=${p#v}
    case "$p" in '' | *[!0-9.]*) ;; *) echo "$p" && return 0 ;; esac
  done
}

install_node() {
  local a v f tmp rc pin d="$HOME/.local/share/node"
  a=$(arch) || return 1
  pin=$(node_pin)
  # index.tab lists releases newest first: the first release matching the pin
  # (or, without one, the first LTS) wins
  v=$(curl -fsSL https://nodejs.org/dist/index.tab | awk -F'\t' -v pin="$pin" 'NR>1 && (pin=="" ? $10!="-" : ($1==("v" pin) || index($1, "v" pin ".")==1)) {print $1; exit}')
  if [ -z "$v" ]; then
    [ -z "$pin" ] || echo "no Node release matches the project's pin: $pin" >&2
    return 1
  fi
  f="node-$v-$(os)-$a.tar.gz"
  tmp=$(mktemp -d "${TMPDIR:-/tmp}/ide.XXXXXX") || return 1
  TMPD=$tmp
  curl -fsSL -o "$tmp/$f" "https://nodejs.org/dist/$v/$f" \
    && curl -fsSL "https://nodejs.org/dist/$v/SHASUMS256.txt" | grep " $f\$" | (cd "$tmp" && sha256 -c -) \
    && mkdir -p "$d" && tar -xzf "$tmp/$f" -C "$d" --strip-components=1 \
    && link "$d/bin/node" && link "$d/bin/npm" && link "$d/bin/npx"
  rc=$?
  rm -rf "$tmp"
  return "$rc"
}

# a system node can be present without npm (e.g. apt install nodejs), so the
# npm-backed recipes check npm itself rather than trusting `ensure node`
need_npm() {
  command -v npm > /dev/null 2>&1 || {
    echo "npm not found: node is present without npm; install npm, then retry" >&2
    return 1
  }
}

install_pnpm() { ensure node && need_npm && npm install -g --prefix "$HOME/.local" pnpm; }

# A corepack yarn shim runs Classic and Berry projects alike (each project's
# packageManager field picks the version); `npm install -g yarn` would only
# give Classic 1.x, which refuses to run in a Berry project. corepack ships
# with node < 25, so fetch it through npm when it is missing.
install_yarn() {
  ensure node && need_npm \
    && { command -v corepack > /dev/null 2>&1 || npm install -g --prefix "$HOME/.local" corepack; } \
    && corepack enable --install-directory "$BIN" yarn
}

# <url> <interpreter> [arg...]: run a downloaded installer script. It goes
# through a temp file, not a pipe, so a failed or truncated download never
# reaches the interpreter. Leading VAR=value assignments reach the script.
fetch_run() {
  local url=$1 sh=$2 s rc
  shift 2
  s=$(mktemp "${TMPDIR:-/tmp}/ide.XXXXXX") || return 1
  TMPD=$s
  curl --proto '=https' --tlsv1.2 -fsSL -o "$s" "$url" && "$sh" "$s" "$@"
  rc=$?
  rm -f "$s"
  return "$rc"
}

# bun's installer puts the binary in $BUN_INSTALL/bin and skips every rc-file
# edit when `command -v bun` resolves (it does: PATH includes ~/.local/bin).
install_bun() { BUN_INSTALL="$HOME/.local" fetch_run https://bun.sh/install bash; }

install_cargo() {
  fetch_run https://sh.rustup.rs sh -y --no-modify-path \
    && link "$CARGO_BIN/cargo" && link "$CARGO_BIN/rustc" && link "$CARGO_BIN/rustup"
}

# `rustup component add` needs rustup itself: a distro cargo alone has none
install_rust_analyzer() {
  ensure cargo && { command -v rustup > /dev/null 2>&1 || install_cargo; } \
    && rustup component add rust-analyzer && link "$CARGO_BIN/rust-analyzer"
}

# GOROOT gets its own directory: ~/.local/share/go is the common XDG GOPATH, and
# GOROOT must never be mixed into a GOPATH tree.
install_go() {
  local a v f tmp rc d="$HOME/.local/share/goroot"
  a=$(arch) || return 1
  if [ "$a" = x64 ]; then a=amd64; fi
  v=$(curl -fsSL 'https://go.dev/VERSION?m=text' | head -n1)
  [ -n "$v" ] || return 1
  f="$v.$(os)-$a.tar.gz"
  tmp=$(mktemp -d "${TMPDIR:-/tmp}/ide.XXXXXX") || return 1
  TMPD=$tmp
  curl -fsSL -o "$tmp/$f" "https://dl.google.com/go/$f" \
    && echo "$(curl -fsSL "https://dl.google.com/go/$f.sha256")  $tmp/$f" | sha256 -c - \
    && mkdir -p "$d" && tar -xzf "$tmp/$f" -C "$d" --strip-components=1 \
    && link "$d/bin/go" && link "$d/bin/gofmt"
  rc=$?
  rm -rf "$tmp"
  return "$rc"
}

install_gopls() { ensure go && GOBIN="$BIN" go install golang.org/x/tools/gopls@latest; }

install_uv() { UV_INSTALL_DIR="$BIN" UV_NO_MODIFY_PATH=1 fetch_run https://astral.sh/uv/install.sh sh; }

# --default links both `python` and `python3`
install_python3() { ensure uv && UV_PYTHON_BIN_DIR="$BIN" uv python install --default; }

install_python() { install_python3; }

install_pylsp() { ensure uv && UV_TOOL_BIN_DIR="$BIN" uv tool install python-lsp-server; }

# LuaLS publishes no checksums (HTTPS only); its tarball is flat (bin/,
# main.lua, ... at the root), so it gets a wrapper rather than a symlink.
install_lua_language_server() {
  local a t f tmp rc d="$HOME/.local/share/lua-language-server" w="$BIN/lua-language-server"
  a=$(arch) || return 1
  t=$(curl -fsSLI -o /dev/null -w '%{url_effective}' https://github.com/LuaLS/lua-language-server/releases/latest)
  t=${t##*/}
  [ -n "$t" ] || return 1
  f="lua-language-server-$t-$(os)-$a.tar.gz"
  tmp=$(mktemp -d "${TMPDIR:-/tmp}/ide.XXXXXX") || return 1
  TMPD=$tmp
  curl -fsSL -o "$tmp/$f" "https://github.com/LuaLS/lua-language-server/releases/download/$t/$f" \
    && mkdir -p "$d" && tar -xzf "$tmp/$f" -C "$d" \
    && if vacant "$w"; then
      printf '%s\n' '#!/usr/bin/env bash' 'exec "$HOME/.local/share/lua-language-server/bin/lua-language-server" "$@"' > "$w" && chmod 755 "$w"
    fi
  rc=$?
  rm -rf "$tmp"
  return "$rc"
}

for id in "$@"; do [ "$id" = "--dry-run" ] || ensure "$id" || FAILED=1; done
if [ -n "$OFFPATH" ]; then
  echo "note: not on PATH (found only via $BIN, $CARGO_BIN or $HOME/.bun/bin):$OFFPATH; add those directories to your shell profile"
fi
exit "$FAILED"
